mapper.delete:
/* file : MatchingMapper.xml, id : deleteMakeModelFile */
DELETE
FROM TB_META_ETC_MODEL_FILES
WHERE ETC_MODEL_SEQ = #{etc_model_seq}
  AND REF_TP IN ('TEST', 'PREDICTION')

/* file : MatchingMapper.xml, id : deleteMakeModelLoss */
DELETE
FROM TB_META_ETC_MODEL_LOSS
WHERE ETC_MODEL_SEQ = #{etc_model_seq}

mapper.update:
/* file : MakeMetaModelSchedulerMapper.xml, id : updateLearningBgngDt */
UPDATE TB_META_ETC_MODEL
SET LEARNING_BGNG_DT = CURRENT_TIMESTAMP
WHERE ETC_MODEL_SEQ = #{etc_model_seq}

/* file : MakeMetaModelSchedulerMapper.xml, id : finishMakeModel */
UPDATE TB_META_ETC_MODEL
SET MODEL_STATUS = #{model_status}
WHERE ETC_MODEL_SEQ = #{etc_model_seq}

/* file : MakeMetaModelSchedulerMapper.xml, id : updateLearningDndDt */
UPDATE TB_META_ETC_MODEL
SET LEARNING_END_DT = CURRENT_TIMESTAMP
WHERE ETC_MODEL_SEQ = #{etc_model_seq}

mapper.select:
/* file : AugmentModelMapper.xml, id : getCountModelFileInfo */
SELECT COUNT(*)
FROM TB_META_ETC_MODEL_FILES A
         JOIN TB_META_ETC_MODEL B ON A.ETC_MODEL_SEQ = B.ETC_MODEL_SEQ AND B.DEL_YN = 'N' AND B.USE_YN = 'Y'
    AND A.DEL_YN = 'N'
    AND A.ETC_MODEL_SEQ = B.ETC_MODEL_SEQ
    AND B.ETC_MODEL_SEQ = #{etc_model_seq}
    AND A.REF_TP = #{ref_tp}

mapper.insert:
/* file : AugmentModelMapper.xml, id : insertModelFileInfo */
INSERT
INTO TB_META_ETC_MODEL_FILES (
FILE_SEQ
, ETC_MODEL_SEQ
, REF_TP
, FILE_NM
, FILE_PATH
, FILE_EXTN
, FILE_SZ
, REG_USER_SEQ
, REG_IP
)
VALUES (
#{fileSeq}
, #{etc_model_seq}
, #{ref_tp}
, #{file_nm}
, #{file_path}
, #{file_extn}
, #{file_size}
, #{reg_user_seq}
, #{reg_ip}
)

    SELECT LAST_INSERT_ID()

mapper.update:
/* file : AugmentModelMapper.xml, id : updateModelFileInfo */
UPDATE TB_META_ETC_MODEL_FILES
SET FILE_NM        = #{file_nm}
  , FILE_PATH      = #{file_path}
  , FILE_EXTN      = #{file_extn}
  , FILE_SZ        = #{file_size}
  , MDFCN_USER_SEQ = #{reg_user_seq}
  , MDFCN_DT       = CURRENT_TIMESTAMP
  , MDFCN_IP       = #{reg_ip}
WHERE ETC_MODEL_SEQ = #{etc_model_seq}
  AND REF_TP = #{ref_tp}

